// D-7: EnTT component set. Transform stays local; WorldTransformComponent is
// generated by Scene::updateWorldTransforms() after hierarchy propagation.
struct TransformComponent
{
    glm::vec3 translation{ 0.0f };
    glm::vec3 scale{ 1.0f, 1.0f, 1.0f };
    glm::vec3 rotation{ 0.0f }; // Euler radians, same convention as before

    glm::mat4 localMatrix() const
    {
        glm::mat4 transform = glm::translate(glm::mat4{ 1.0f }, translation);
        transform = glm::rotate(transform, rotation.y, { 0.0f, 1.0f, 0.0f });
        transform = glm::rotate(transform, rotation.x, { 1.0f, 0.0f, 0.0f });
        transform = glm::rotate(transform, rotation.z, { 0.0f, 0.0f, 1.0f });
        transform = glm::scale(transform, scale);
        return transform;
    }
};

struct HierarchyComponent
{
    entt::entity parent = entt::null;
    std::vector<entt::entity> children;
};

struct WorldTransformComponent
{
    glm::mat4 matrix{ 1.0f };
    glm::mat4 normalMatrix{ 1.0f };
    glm::vec3 worldPosition{ 0.0f };
};

struct MeshComponent
{
    std::shared_ptr<Model> model;
};

struct MaterialComponent
{
    std::shared_ptr<Material> material;
    uint32_t materialSetIndex = kInvalidMaterialSlot;
};

struct RenderTagComponent
{
    bool isSkybox = false;
    bool isGrid = false;
};

struct BoundsComponent
{
    AABB local;
};

struct WorldBoundsComponent
{
    AABB world;
};

// Tag component: this entity is the scene camera, not a renderable object.
struct CameraComponent
{
};

inline AABB transformAABB(const AABB& local, const glm::mat4& transform)
{
    if (!local.valid)
        return AABB{};

    AABB world;
    world.valid = true;

    const glm::vec3 corners[8] = {
        { local.min.x, local.min.y, local.min.z },
        { local.max.x, local.min.y, local.min.z },
        { local.min.x, local.max.y, local.min.z },
        { local.max.x, local.max.y, local.min.z },
        { local.min.x, local.min.y, local.max.z },
        { local.max.x, local.min.y, local.max.z },
        { local.min.x, local.max.y, local.max.z },
        { local.max.x, local.max.y, local.max.z },
    };

    world.min = glm::vec3(transform * glm::vec4(corners[0], 1.0f));
    world.max = world.min;

    for (int i = 1; i < 8; ++i)
    {
        const glm::vec3 p = glm::vec3(transform * glm::vec4(corners[i], 1.0f));
        world.min = glm::min(world.min, p);
        world.max = glm::max(world.max, p);
    }

    return world;
}